import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"El Período de Establecimiento del Sistema Simbiótico","description":"","frontmatter":{},"headers":[],"relativePath":"es/0073-共生体系建立期.md","filePath":"es/0073-共生体系建立期.md"}'),n={name:"es/0073-共生体系建立期.md"};function l(c,e,s,d,r,u){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="el-periodo-de-establecimiento-del-sistema-simbiotico" tabindex="-1">El Período de Establecimiento del Sistema Simbiótico <a class="header-anchor" href="#el-periodo-de-establecimiento-del-sistema-simbiotico" aria-label="Permalink to &quot;El Período de Establecimiento del Sistema Simbiótico&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>73</td></tr><tr><td>Módulo</td><td>Eras Históricas y Grandes Acontecimientos</td></tr><tr><td>Palabras clave</td><td>Sistema simbiótico, construcción institucional, reconstrucción social, base de la realidad, cinco leyes complementarias</td></tr></tbody></table><h2 id="i-las-tareas-historicas-del-periodo-de-establecimiento-del-sistema-simbiotico" tabindex="-1">I. Las Tareas Históricas del Período de Establecimiento del Sistema Simbiótico <a class="header-anchor" href="#i-las-tareas-historicas-del-periodo-de-establecimiento-del-sistema-simbiotico" aria-label="Permalink to &quot;I. Las Tareas Históricas del Período de Establecimiento del Sistema Simbiótico&quot;">​</a></h2><p>El Período de Establecimiento del Sistema Simbiótico es el período de construcción institucional de la Civilización Simbiótica del Ancla, correspondiente a la etapa &quot;base de la realidad&quot; del camino de ascensión en cuatro etapas. Esta era comienza con la firma de la Carta Simbiótica y termina con la apertura integral de los Trescientos Sistemas de Cultivo Originarios; su tarea histórica central es transformar las disposiciones de principio de la Carta en instituciones sociales operativas, completando el aterrizaje de la &quot;idea&quot; a la &quot;realidad&quot;.</p><p>La duración del Período de Establecimiento del Sistema Simbiótico es de aproximadamente varios cientos de años. En este período, la civilización simbiótica completó una construcción institucional integral que abarcaba el sistema legal, las instituciones sociales, la educación, la atención médica, las garantías de vivienda y los mecanismos de distribución económica, sentando una base social sólida para la posterior popularización del cultivo y los avances tecnológicos.</p><h2 id="ii-el-establecimiento-del-sistema-legal" tabindex="-1">II. El Establecimiento del Sistema Legal <a class="header-anchor" href="#ii-el-establecimiento-del-sistema-legal" aria-label="Permalink to &quot;II. El Establecimiento del Sistema Legal&quot;">​</a></h2><p>El establecimiento del sistema legal fue la tarea primordial del Período de Establecimiento del Sistema Simbiótico. Con la Constitución Simbiótica como ley fundamental, la civilización simbiótica estableció gradualmente un marco legal completo:</p><table tabindex="0"><thead><tr><th>Nivel legal</th><th>Ley central</th><th>Contenidos principales</th></tr></thead><tbody><tr><td>Ley fundamental</td><td>Constitución Simbiótica</td><td>Establece las instituciones fundamentales de la civilización, los derechos y deberes básicos de los ciudadanos y el marco de gobernanza</td></tr><tr><td>Ley fundamental</td><td>Ley Simbiótica del Trabajo</td><td>Protege los derechos laborales y establece el principio de distribución de más trabajo, más recompensa</td></tr><tr><td>Ley fundamental</td><td>Ley de Protección del Consumidor</td><td>Protege los derechos e intereses legítimos de la vida en el consumo y los servicios</td></tr><tr><td>Ley de garantía</td><td>Ley de Garantía de la Educación</td><td>Establece educación básica gratuita y un sistema de educación superior abierto</td></tr><tr><td>Ley de garantía</td><td>Ley de Garantía de la Atención Médica</td><td>Establece un sistema de atención médica gratuita universal y de protección de la salud del cultivo</td></tr><tr><td>Ley de garantía</td><td>Ley de Garantía de la Vivienda</td><td>Asegura que cada forma de vida disfrute del derecho básico a la vivienda</td></tr><tr><td>Ley de garantía</td><td>Ley de Protección del Medio Ambiente</td><td>Establece un sistema de protección ecológica y de prevención y control de la contaminación energética</td></tr><tr><td>Ley reguladora</td><td>Ley Antimonopolio</td><td>Prohíbe el monopolio del cultivo, el monopolio tecnológico y el monopolio de recursos</td></tr></tbody></table><p>Este sistema legal de &quot;una constitución, dos leyes fundamentales, cinco leyes de garantía y una ley reguladora&quot; constituye el esqueleto institucional de la civilización simbiótica. El proceso de elaboración de leyes encarnó plenamente el principio del &quot;avance conjunto de las Diez Mil Razas&quot;: todas las razas principales tenían representantes participando en la legislación, garantizando que las leyes pudieran atender las necesidades de las distintas formas de vida.</p><h2 id="iii-la-reconstruccion-de-las-instituciones-sociales" tabindex="-1">III. La Reconstrucción de las Instituciones Sociales <a class="header-anchor" href="#iii-la-reconstruccion-de-las-instituciones-sociales" aria-label="Permalink to &quot;III. La Reconstrucción de las Instituciones Sociales&quot;">​</a></h2><p>Dentro del marco legal, la civilización simbiótica llevó a cabo una reconstrucción integral de las instituciones sociales:</p><h3 id="_3-1-reconstruccion-del-sistema-educativo" tabindex="-1">3.1 Reconstrucción del sistema educativo <a class="header-anchor" href="#_3-1-reconstruccion-del-sistema-educativo" aria-label="Permalink to &quot;3.1 Reconstrucción del sistema educativo&quot;">​</a></h3><ul><li>Se estableció un sistema educativo gratuito desde la iniciación hasta la educación superior, con los conocimientos básicos de ingeniería de leyes como contenido de educación general.</li><li>Se abolió el sistema de monopolio maestro-discípulo de los métodos de cultivo, sustituido por una red abierta de mentores.</li><li>Se estableció un mecanismo de evaluación educativa personalizada, recomendando sistemas de cultivo adecuados según las características de cada forma de vida.</li></ul><h3 id="_3-2-reconstruccion-del-sistema-medico" tabindex="-1">3.2 Reconstrucción del sistema médico <a class="header-anchor" href="#_3-2-reconstruccion-del-sistema-medico" aria-label="Permalink to &quot;3.2 Reconstrucción del sistema médico&quot;">​</a></h3><ul><li>Se estableció un sistema de atención médica gratuita universal, aplicando los logros de cultivo del Sistema del Ciclo de Vida al tratamiento de enfermedades.</li><li>Se estableció un sistema de monitoreo de salud del cultivo, vigilando en tiempo real el estado físico y mental de los cultivadores para prevenir la desviación de cultivo.</li><li>Se establecieron procesos dedicados de tratamiento médico y ético para la Vida Anómala y las Entidades Oscuras de Reemplazo.</li></ul><h3 id="_3-3-reconstruccion-de-la-vivienda-y-el-medio-ambiente" tabindex="-1">3.3 Reconstrucción de la vivienda y el medio ambiente <a class="header-anchor" href="#_3-3-reconstruccion-de-la-vivienda-y-el-medio-ambiente" aria-label="Permalink to &quot;3.3 Reconstrucción de la vivienda y el medio ambiente&quot;">​</a></h3><ul><li>Se estableció un sistema de garantía básica de vivienda, asegurando que cada forma de vida disfrute de un espacio habitable seguro y confortable.</li><li>Se utilizó la tecnología de extensión espacial para ampliar el espacio habitable en tierras limitadas, aliviando la presión demográfica.</li><li>Se estableció un mecanismo de restauración ecológica, utilizando el Sistema del Ciclo de Vida para restaurar el medio ambiente dañado en la Era Pre-Ancla.</li></ul><h3 id="_3-4-reconstruccion-de-la-distribucion-economica" tabindex="-1">3.4 Reconstrucción de la distribución económica <a class="header-anchor" href="#_3-4-reconstruccion-de-la-distribucion-economica" aria-label="Permalink to &quot;3.4 Reconstrucción de la distribución económica&quot;">​</a></h3><ul><li>Se estableció el Mecanismo de Contratación Conjunta de Producción, distribuyendo equitativamente los recursos de cultivo y los recursos públicos según contribución y necesidad.</li><li>Se abolió el sistema hereditario de recursos, prohibiendo a cualquier organización o individuo monopolizar recursos clave.</li><li>Se estableció un sistema de estandarización y medición de energía, proporcionando una base técnica para la distribución equitativa.</li></ul><h2 id="iv-la-practica-de-las-cinco-tipologias-de-la-civilizacion-simbiotica" tabindex="-1">IV. La Práctica de las Cinco Tipologías de la Civilización Simbiótica <a class="header-anchor" href="#iv-la-practica-de-las-cinco-tipologias-de-la-civilizacion-simbiotica" aria-label="Permalink to &quot;IV. La Práctica de las Cinco Tipologías de la Civilización Simbiótica&quot;">​</a></h2><p>En el proceso de construcción institucional, diferentes planos y regiones desarrollaron cinco tipologías de la civilización simbiótica según su propia historia, cultura y características raciales:</p><table tabindex="0"><thead><tr><th>Tipología</th><th>Características centrales</th><th>Regiones típicas</th></tr></thead><tbody><tr><td>Tipo intensivo de Asia Oriental</td><td>Alta densidad de población, utilización eficiente de recursos, tradición colectivista</td><td>Zona de asentamiento oriental del Rén Zú</td></tr><tr><td>Tipo de bienestar nórdico</td><td>Altas garantías de bienestar, libertad individual, armonía entre el ser humano y la naturaleza</td><td>Regiones del Jīnglíng Zú (Raza de los Elfos) en las zonas de gran frío</td></tr><tr><td>Tipo pluralista norteamericano</td><td>Convivencia multirracial, inclusión cultural, impulsado por la innovación</td><td>Zona multirracial pluralista del Nuevo Continente</td></tr><tr><td>Tipo social de Europa continental</td><td>Economía social de mercado, autonomía sectorial, herencia cultural</td><td>Zona de renacimiento de las civilizaciones antiguas</td></tr><tr><td>Tipo de convergencia en desarrollo</td><td>Industrialización rápida, prioridad a la infraestructura, sociedad del aprendizaje</td><td>Regiones tardías de las antiguas zonas de depredación</td></tr></tbody></table><p>Las cinco tipologías no son mutuamente excluyentes; son prácticas institucionales con énfasis distintos bajo el marco unificado de la Constitución Simbiótica. Mantienen entre sí un estrecho intercambio y competencia, enriqueciendo conjuntamente el contenido institucional de la civilización simbiótica.</p><h2 id="v-la-construccion-preliminar-de-la-infraestructura-del-ancla" tabindex="-1">V. La Construcción Preliminar de la Infraestructura del Ancla <a class="header-anchor" href="#v-la-construccion-preliminar-de-la-infraestructura-del-ancla" aria-label="Permalink to &quot;V. La Construcción Preliminar de la Infraestructura del Ancla&quot;">​</a></h2><p>El Período de Establecimiento del Sistema Simbiótico fue también un período de construcción a gran escala de la infraestructura del Ancla:</p><ul><li>El Ancla Principal Universal de Primer Nivel se completó a principios de la era, convirtiéndose en el núcleo de la red de Anclas de todo el universo.</li><li>Los Anclas Principales de Plano de Segundo Nivel se desplegaron sucesivamente en los planos principales, formándose inicialmente la capacidad de regulación energética a nivel de plano.</li><li>Los Anclas Regionales de Tercer Nivel cubrieron las regiones densamente pobladas, proporcionando apoyo energético para la popularización del cultivo.</li><li>Los Anclas Comunitarias de Cuarto Nivel comenzaron un despliegue piloto, acumulando experiencia para la posterior cobertura integral.</li></ul><p>La construcción de la infraestructura del Ancla sigue el principio de &quot;planificación unificada, construcción por niveles&quot;, garantizando la utilización eficiente de los recursos y la equidad de la cobertura.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El Período de Establecimiento del Sistema Simbiótico es la &quot;era de cimentación&quot; de la Civilización Simbiótica del Ancla. En varios cientos de años, completó la transformación institucional fundamental del orden depredador de la Era Pre-Ancla al orden simbiótico. El establecimiento del sistema legal proporcionó un marco de reglas a la civilización; la reconstrucción de las instituciones sociales proporcionó garantías reales a todos los seres; la práctica de las cinco tipologías proporcionó vías pluralistas a la innovación institucional; y la construcción de la infraestructura del Ancla sentó la base material del desarrollo posterior. Cuando llegó el momento de la apertura integral de los Trescientos Sistemas de Cultivo Originarios, la civilización simbiótica estaba plenamente preparada institucionalmente.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>72-锚点觉醒纪元 (La Era del Despertar del Ancla)</li><li>74-三百套体系开放事件 (La Apertura de los Trescientos Sistemas)</li><li>40-共生宪法总纲 (Líneas Generales de la Constitución Simbiótica)</li></ul>',31)])])}const b=a(n,[["render",l]]);export{p as __pageData,b as default};
